```python
from typing import List, Callable

class EventEmitter:
    """事件发布订阅（观察者模式）"""
    def __init__(self):
        self._handlers: dict[str, List[Callable]] = {}

    def on(self, event: str, handler: Callable) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def off(self, event: str, handler: Callable) -> None:
        if event in self._handlers:
            self._handlers[event].remove(handler)

    def emit(self, event: str, *args, **kwargs) -> None:
        for handler in self._handlers.get(event, []):
            handler(*args, **kwargs)

# 使用示例
emitter = EventEmitter()

def on_login(user_id: str):
    print(f'User {user_id} logged in')

def send_welcome(user_id: str):
    print(f'Sending welcome email to {user_id}')

emitter.on('user:login', on_login)
emitter.on('user:login', send_welcome)
emitter.emit('user:login', 'alice')  # 触发所有订阅者
```

斐波那契：F(n) = F(n-1) + F(n-2)，序列：0,1,1,2,3,5,8,13...

```python
# 朴素递归 — O(2^n)，指数爆炸
def fib_naive(n):
    if n <= 1: return n
    return fib_naive(n-1) + fib_naive(n-2)

# 记忆化 — O(n) 时间，O(n) 空间
from functools import lru_cache
@lru_cache
def fib_memo(n):
    if n <= 1: return n
    return fib_memo(n-1) + fib_memo(n-2)

# 迭代DP — O(n) 时间，O(1) 空间（最优）
def fib_dp(n):
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return b

print(fib_dp(50))  # 12586269025
```

**DP 三要素**：状态定义、转移方程、初始条件

