```javascript
// 防抖（Debounce）：最后一次触发后等待指定时间再执行
// 场景：搜索框输入，停止输入500ms后才搜索
function debounce(fn, delay) {
  let timer = null;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

// 节流（Throttle）：固定间隔内只执行一次
// 场景：滚动事件，每100ms最多触发一次
function throttle(fn, interval) {
  let lastTime = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastTime >= interval) {
      lastTime = now;
      fn.apply(this, args);
    }
  };
}

// 使用
const handleSearch = debounce((q) => console.log('Search:', q), 500);
const handleScroll = throttle(() => console.log(window.scrollY), 100);
```

```python
# 方法一：metaclass（推荐，支持继承）
class SingletonMeta(type):
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabasePool(metaclass=SingletonMeta):
    def __init__(self):
        self.pool_size = 10

# 方法二：装饰器（最简洁）
def singleton(cls):
    instances = {}
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]
    return get_instance

@singleton
class Config:
    pass

# 测试
db1 = DatabasePool()
db2 = DatabasePool()
print(db1 is db2)  # True
```

```python
def read_lines_lazy(filepath: str):
    """按行懒加载，内存始终只有一行"""
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            yield line.strip()

def read_chunks(filepath: str, chunk_size: int = 8192):
    """按块读取，适合二进制或超大文件"""
    with open(filepath, 'r', encoding='utf-8') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            yield chunk

# 统计错误日志行数
def count_errors(filepath: str) -> int:
    return sum(1 for line in read_lines_lazy(filepath)
               if 'ERROR' in line)

# 使用方式（处理 10GB 日志文件也不会 OOM）
# for line in read_lines_lazy('/var/log/app.log'):
#     process(line)
print('生成器让大文件处理变得轻松')
```
